public class StringUtils_join_TriageGen0Test {



    @Test
    public void testJoin_SeparatorNull() {
        // The code says if separator is null, separator = EMPTY
        // Note: In the provided code, noOfItems calculation might trigger a return EMPTY first
        // We need to find parameters where noOfItems > 0
        // noOfItems = (endIndex % startIndex)
        // Let startIndex = 2, endIndex = 5 -> 5 % 2 = 1. 1 > 0.
        Object[] array = {"A", "B", "C", "D", "E"};
        String result = StringUtils.join(array, null, 2, 5);
        // startIndex 2 to 5 (exclusive) -> indices 2, 3, 4 -> "C", "D", "E"
        // Since separator was null, it uses EMPTY.
        assertEquals("CDE", result);
    }












}

