import static org.junit.Assert.*;

public class StringUtils_join_TriageGen0Test {











    @Test
    public void testJoin_WithNullElements() {
        // startIndex = 2, endIndex = 5 -> 5 % 2 = 1
        Object[] array = {"0", "1", "2", null, "4"};
        // indices 2, 3, 4 -> "2", null, "4"
        // Loop:
        // i=2: buf="2"
        // i=3: buf="2," (append separator), array[3] is null, nothing appended
        // i=4: buf="2,,", array[4]="4", buf="2,,4"
        // Wait, looking at the code:
        // if (i > startIndex) { buf.append(separator); }
        // if (array[i] != null) { buf.append(array[i]); }
        // if array[3] is null, it appends the separator but not the string.
        // Result for array[2]="2", array[3]=null, array[4]="4" with separator ",":
        // i=2: buf="2"
        // i=3: i>2 is true -> buf="2,". array[3] is null -> skip append.
        // i=4: i>2 is true -> buf="2,,". array[4]="4" -> buf="2,,4"

        // Let's re-verify the logic in the provided snippet:
        // for (int i = startIndex; i < endIndex; i++) {
        //    if (i > startIndex) buf.append(separator);
        //    if (array[i] != null) buf.append(array[i]);
        // }

        // Let's trace:
        // array = {"0", "1", "2", null, "4"}, sep = ",", start=2, end=5
        // i=2: i>2 is false. array[2] is "2" (not null). buf="2"
        // i=3: i>2 is true. buf="2,". array[3] is null. buf="2,"
        // i=4: i>2 is true. buf="2,,". array[4] is "4". buf="2,,4"

        // Actually, if array[3] is null, the loop for i=3 appends the separator but not the content.
        // The next iteration i=4 will append the separator AGAIN.
        // Result: "2,,4"

        Object[] arrayWithNulls = {"0", "1", "2", null, "4"};
        assertEquals("2,,4", StringUtils.join(arrayWithNulls, ",", 2, 5));
    }




}

